sit.example:
kcds.core.Events.on('playerCommand', (player, command) => {
  if (command === 'play') {
    table.sit(player, table.seats.findIndex((seat) => seat.player === null));
  }
});

sit.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command == "play")
    {
        table.Sit(player, table.Seats.Call("findIndex", (JsValue seat) => seat["player"].IsNull));
    }
});

start.example:
kcds.core.Events.on('tabletopSit', (table) => {
  setTimeout(() => {
    if (table.state === 'idle' && table.seats.every((seat) => seat.player)) {
      table.start();
    }
  }, 0);
});

start.exampleCs:
Events.On("tabletopSit", (JsValue table) =>
{
    Timers.SetTimeout(() =>
    {
        if (table["state"].AsString() == "idle" && table["seats"].All(seat => seat["player"]))
        {
            table.Call("start");
        }
    }, 0);
});

nextTurn.exampleLua:
kcds.core.Events.on("tabletopMoveRequest", function(table)
  setTimeout(function() return table:nextTurn() end, 0)
end)

bet.example:
if (!(await table.bet(20))) {
