clear.exampleLua:
kcds.core.Events.on("tabletopEnd", function(table)
  setTimeout(function() return table:clear() end, 5000)
end)

save.example:
kcds.core.Events.on('resourceStop', () => {
  const text = JSON.stringify(table.save());
  console.info(`board saved, ${text.length} characters`);
});

save.exampleCs:
Events.On("resourceStop", () =>
{
    var text = table.Save().ToJson();
    Log.Info($"board saved, {text.Length} characters");
});
